package com.tihai.controller;
import com.tihai.utils.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import org.springframework.web.servlet.*;import org.springframework.web.servlet.config.annotation.InterceptorRegistry;import org.springframework.web.bind.annotation.*;import java.util.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ScopeHttpTest {
 @TempDir Path root;AccountRegistry registry;MockMvc mvc;String a,b,rain;
 static class ExposedRegistry extends InterceptorRegistry {HandlerInterceptor[] items(){return getInterceptors().toArray(new HandlerInterceptor[0]);}}
 @RestController static class FakeController {@GetMapping("/local/probe")public Map probe(){return Collections.singletonMap("account",AccountScope.account());}@PostMapping({"/local/tasks/{id}/delete","/local/assessments/detail","/local/exams/start","/local/signin/start","/local/review/export"})public Map mutate(@RequestBody Map<String,Object> body){return Collections.singletonMap("mutated",true);}@GetMapping("/local/review/questions")public Map questions(){return Collections.singletonMap("read",true);}}
 @BeforeEach void setup()throws Exception{registry=new AccountRegistry(root);a=registry.registerChaoxing("account-a",true);b=registry.registerChaoxing("account-b",false);rain=String.valueOf(registry.addRain("Rain","https://www.yuketang.cn/").get("id"));registry.select("chaoxing",a);registry.attachTask("task-a",a);registry.attachTask("task-b",b);registry.resource("assessment","work-b","account-b");registry.resource("exam","exam-b","account-b");registry.resource("signin","sign-b","account-b");AccountScopeConfiguration config=new AccountScopeConfiguration();ReflectionTestUtils.setField(config,"registry",registry);ExposedRegistry interceptors=new ExposedRegistry();config.addInterceptors(interceptors);ScopeBodyAdvice advice=new ScopeBodyAdvice();ReflectionTestUtils.setField(advice,"registry",registry);mvc=MockMvcBuilders.standaloneSetup(new FakeController()).setControllerAdvice(advice).addInterceptors(interceptors.items()).build();}
 @AfterEach void clear()throws Exception{AccountScope.clear();WindowsTestCleanup.remove(root);}
 @Test void missingHeaderUsesSelectedAccountAndExplicitHeadersChooseOnlyOneAccount()throws Exception{mvc.perform(get("/local/probe")).andExpect(status().isOk()).andExpect(jsonPath("$.account").value("account-a"));mvc.perform(get("/local/probe").header("X-Study-Platform","chaoxing").header("X-Study-Account",b)).andExpect(jsonPath("$.account").value("account-b"));assertFalse(AccountScope.scoped());}
 @Test void mismatchedPlatformAndUnknownAccountAreRejected()throws Exception{mvc.perform(get("/local/probe").header("X-Study-Platform","chaoxing").header("X-Study-Account",rain)).andExpect(status().isBadRequest());mvc.perform(get("/local/probe").header("X-Study-Account","missing")).andExpect(status().isBadRequest());}
 @Test void allForeignTaskAndAssessmentActionsAreBlockedBeforeControllerRuns()throws Exception{for(String[] item:new String[][]{{"/local/tasks/task-b/delete","{}"},{"/local/assessments/detail","{\"id\":\"work-b\"}"},{"/local/exams/start","{\"id\":\"exam-b\"}"},{"/local/signin/start","{\"id\":\"sign-b\"}"},{"/local/review/export","{\"course\":\"task-b\"}"}})mvc.perform(post(item[0]).header("X-Study-Account",a).contentType("application/json").content(item[1])).andExpect(status().isForbidden());mvc.perform(post("/local/tasks/task-a/delete").contentType("application/json").content("{}")).andExpect(status().isOk());}
 @Test void reviewGetCannotReadAnotherAccountsLibrary()throws Exception{mvc.perform(get("/local/review/questions?course=task-b")).andExpect(status().isForbidden());mvc.perform(get("/local/review/questions?course=task-a")).andExpect(status().isOk());}
}
